-- Initial schema and additive upgrade from the pre-Flyway portal.
-- Baseline version 0 preserves existing accounts, profiles, jobs and audits.
create sequence if not exists workspace_ids start with 2 increment by 1;
create table if not exists asset_storage (retention_days integer not null, id bigint not null, revision bigint, active_version varchar(255), draft_version varchar(255), primary key (id));
create table if not exists audit_event (legacy_imported boolean default false not null, chain_index bigint, created_at timestamp(6) with time zone, id bigint generated by default as identity, workspace_id bigint default 1 not null, action varchar(255), actor varchar(255), hash varchar(255), previous_hash varchar(255), reference varchar(255), primary key (id), unique (workspace_id, chain_index));
create table if not exists audit_head (event_count bigint not null, id bigint not null, revision bigint, hash varchar(255), primary key (id));
create table if not exists configuration_record (active_revision bigint, id bigint not null, revision bigint, active varchar(16000), draft varchar(16000), primary key (id));
create table if not exists configuration_version (configuration_revision bigint, created_at timestamp(6) with time zone, id bigint generated by default as identity, workspace_id bigint default 1 not null, settings varchar(16000), action varchar(255), primary key (id));
create table if not exists encrypted_credential (created_at timestamp(6) with time zone, workspace_id bigint not null, key_fingerprint varchar(64) not null, label varchar(80) not null, sealed varchar(64000) not null, id varchar(255) not null, primary key (id));
create table if not exists job_notification (created_at timestamp(6) with time zone, read_at timestamp(6) with time zone, workspace_id bigint, event_key varchar(255) not null unique, id varchar(255) not null, job_id varchar(255), outcome varchar(255), owner varchar(255), primary key (id));
create table if not exists login_session (expires_at timestamp(6) with time zone, user_id bigint, token_hash varchar(255) not null, primary key (token_hash));
create table if not exists portal_api_key (revoked boolean not null, created_at timestamp(6) with time zone, expires_at timestamp(6) with time zone, user_id bigint, workspace_id bigint, token_hash varchar(64) not null unique, id varchar(255) not null, label varchar(255), scopes varchar(255), primary key (id));
create table if not exists portal_user (enabled boolean not null, failed_logins integer not null, password_change_required boolean default false not null, id bigint generated by default as identity, locked_until timestamp(6) with time zone, password_hash varchar(255) not null, role varchar(255), username varchar(255) not null unique, primary key (id));
create table if not exists processing_settings (max_attempts integer not null, worker_timeout_seconds integer not null, id bigint not null, revision bigint, primary key (id));
create table if not exists signing_job (attempts integer not null, max_attempts integer default 10 not null, worker_timeout_seconds integer default 45 not null, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone, lease_until timestamp(6) with time zone, revision bigint, workspace_id bigint default 1 not null, attempt_directories varchar(8000), storage_snapshot varchar(16000), certificate_path varchar(255), error varchar(255), fingerprint varchar(255), format varchar(255), id varchar(255) not null, key_path varchar(255), lease_token varchar(255), owner varchar(255), request_digest varchar(255), request_key varchar(255) unique, result_attempt varchar(255), state varchar(255), title varchar(255), primary key (id));
create table if not exists storage_version (created_at timestamp(6) with time zone, tested_at timestamp(6) with time zone, workspace_id bigint not null, configuration varchar(16000) not null, id varchar(255) not null, primary key (id));
create table if not exists webhook_delivery (attempts integer not null, status_code integer, created_at timestamp(6) with time zone, next_attempt_at timestamp(6) with time zone, revision bigint, workspace_id bigint, payload varchar(8000), configuration varchar(16000), event_key varchar(255) not null unique, id varchar(255) not null, state varchar(255), primary key (id));
create table if not exists webhook_settings (id bigint not null, revision bigint, active_version varchar(255), draft_version varchar(255), primary key (id));
create table if not exists webhook_version (created_at timestamp(6) with time zone, tested_at timestamp(6) with time zone, workspace_id bigint, configuration varchar(16000), id varchar(255) not null, primary key (id));
create table if not exists workspace (legacy_memberships_imported boolean default false not null, id bigint not null, revision bigint default 0 not null, name varchar(120) not null, slug varchar(255) not null unique, primary key (id));
create table if not exists workspace_membership (id bigint generated by default as identity, revision bigint, user_id bigint not null, workspace_id bigint not null, role varchar(255) not null, primary key (id), unique (workspace_id, user_id));

-- Columns introduced after the original portal schema.
alter table asset_storage add column if not exists active_version varchar(255);
alter table asset_storage add column if not exists draft_version varchar(255);
alter table audit_event add column if not exists workspace_id bigint default 1 not null;
alter table audit_event add column if not exists legacy_imported boolean default false not null;
alter table audit_event add column if not exists chain_index bigint;
alter table audit_event add column if not exists previous_hash varchar(255);
alter table audit_event add column if not exists hash varchar(255);
alter table configuration_record add column if not exists active_revision bigint;
alter table configuration_version add column if not exists workspace_id bigint default 1 not null;
alter table portal_user add column if not exists password_change_required boolean default false not null;
alter table portal_user add column if not exists failed_logins integer default 0 not null;
alter table portal_user add column if not exists locked_until timestamp(6) with time zone;
alter table workspace add column if not exists legacy_memberships_imported boolean default false not null;
alter table workspace add column if not exists revision bigint default 0 not null;
alter table signing_job add column if not exists workspace_id bigint default 1 not null;
alter table signing_job add column if not exists storage_snapshot varchar(16000);
alter table signing_job add column if not exists max_attempts integer default 10 not null;
alter table signing_job add column if not exists worker_timeout_seconds integer default 45 not null;
alter table signing_job add column if not exists lease_token varchar(255);
alter table signing_job add column if not exists lease_until timestamp(6) with time zone;
alter table signing_job add column if not exists result_attempt varchar(255);
alter table signing_job add column if not exists attempt_directories varchar(8000);
alter table workspace_membership add column if not exists revision bigint;
create unique index if not exists audit_chain_position on audit_event(workspace_id,chain_index);
create index if not exists job_queue on signing_job(state,created_at);
create index if not exists workspace_jobs on signing_job(workspace_id,owner,created_at);
create index if not exists webhook_pending on webhook_delivery(state,next_attempt_at);
create index if not exists workspace_audits on audit_event(workspace_id,id);
create index if not exists workspace_notifications on job_notification(workspace_id,owner,created_at);
